import { useEffect, useState } from "react";
import api from "@/lib/api";
import { Link, Navigate } from "react-router-dom";
import { useAuth } from "@/context/AuthContext";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";

const STATUS_STYLE = {
  placed: "bg-amber-100 text-amber-800",
  confirmed: "bg-blue-100 text-blue-800",
  rider_assigned: "bg-indigo-100 text-indigo-800",
  delivered: "bg-green-100 text-green-800",
  cancelled: "bg-red-100 text-red-800",
};

export default function MyOrders() {
  const { user, loading } = useAuth();
  const [orders, setOrders] = useState([]);
  useEffect(() => { if (user) api.get("/orders/my").then((r) => setOrders(r.data)); }, [user]);
  if (loading) return <div className="py-20 text-center">Loading...</div>;
  if (!user) return <Navigate to="/login" />;

  return (
    <div className="max-w-5xl mx-auto px-4 py-10" data-testid="my-orders-page">
      <h1 className="font-display text-3xl md:text-4xl font-bold mb-6">My Orders</h1>
      {orders.length === 0 ? (
        <div className="text-center py-16 text-[#5C4A3D]">No orders yet. <Link to="/categories" className="text-[#D97706] font-semibold">Start shopping</Link></div>
      ) : (
        <div className="space-y-3">
          {orders.map((o) => (
            <div key={o.id} className="bg-white border border-[#E6DFD5] rounded-2xl p-5 flex flex-col md:flex-row gap-4 md:items-center" data-testid={`order-${o.order_no}`}>
              <div className="flex-1">
                <div className="flex items-center gap-2">
                  <div className="font-semibold">{o.order_no}</div>
                  <Badge className={STATUS_STYLE[o.status]}>{o.status.replace("_", " ")}</Badge>
                </div>
                <div className="text-xs text-[#5C4A3D] mt-1">{new Date(o.created_at).toLocaleString()}</div>
                <div className="text-sm mt-2">{o.items?.length} items · ₹{o.total?.toFixed(0)} · {o.payment_method}</div>
              </div>
              <Link to={`/orders/${o.id}`}><Button variant="outline" className="rounded-full" data-testid={`view-order-${o.order_no}`}>View Details</Button></Link>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
